name: No Response

on:
  schedule:
    - cron: '0 0 * * *'
  workflow_dispatch:

jobs:
  no-response:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
          token: ${{ secrets.GITHUB_TOKEN }}
      - uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            // Check if the issue has been inactive for more than 14 days
            const { owner, repo } = context.repo;
            const issueNumber = 2083; // The specific issue number

            // Get the issue
            const issue = await github.rest.issues.get({
              owner,
              repo,
              issue_number: issueNumber
            });

            // If the issue is already closed, do nothing
            if (issue.data.state === 'closed') {
              console.log(`Issue #${issueNumber} is already closed`);
              return;
            }

            // Calculate the date 14 days ago
            const fourteenDaysAgo = new Date();
            fourteenDaysAgo.setDate(fourteenDaysAgo.getDate() - 14);

            // Check if the issue was last updated before 14 days ago
            const lastUpdated = new Date(issue.data.updated_at);
            if (lastUpdated < fourteenDaysAgo) {
              // Close the issue with a message
              await github.rest.issues.update({
                owner,
                repo,
                issue_number: issueNumber,
                state: 'closed',
                state_reason: 'not_planned'
              });

              // Add a comment explaining why it was closed
              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number: issueNumber,
                body: 'This issue has been automatically closed due to lack of response for more than 14 days. If you still need help, feel free to re-open or create a new issue.'
              });

              console.log(`Issue #${issueNumber} closed due to no response`);
            } else {
              console.log(`Issue #${issueNumber} is still active`);
            }
